<script setup>
import {ref,computed} from 'vue'
import {sourceRecords} from './sourceRecords'
const props=defineProps({country:{type:String,default:''},industry:{type:String,default:''}})
const search=ref(''),kind=ref('全部'),curation=ref('all')
const groups=[{id:'all',label:'全部资料'},{id:'manual',label:'人工整理'},{id:'ai',label:'AI 整理'}]
const records=computed(()=>sourceRecords.filter(r=>(curation.value==='all'||r.curation===curation.value)&&(!props.country||r.country===props.country)&&(!props.industry||r.industry===props.industry)&&(kind.value==='全部'||r.kind===kind.value)&&(!search.value.trim()||`${r.title} ${r.summary} ${r.publisher}`.includes(search.value.trim()))))
</script>
<template><section class="official-sources"><div class="section-title"><h2>官方信息与政策</h2><small>资料快照 · 2026-11-28</small></div><div class="curation-tabs" role="group" aria-label="资料整理方式"><button v-for="g in groups" :key="g.id" :aria-pressed="curation===g.id" :class="{selected:curation===g.id}" @click="curation=g.id">{{g.label}}</button></div><div class="source-filters"><el-input v-model="search" aria-label="搜索官方资料" placeholder="搜索标题、内容或机构" clearable/><el-select v-model="kind" aria-label="资料类型"><el-option v-for="k in ['全部','市场数据','政策公告']" :value="k" :label="k"/></el-select></div><p v-if="!records.length" role="status">当前分类暂无匹配资料</p><article v-for="r in records" :key="r.id" class="official-card"><div class="source-meta"><span>{{r.kind}} · {{r.country}}</span><span class="curation-badge" :class="r.curation">{{r.curation==='manual'?'人工整理':'AI 整理'}}</span><span :class="{historical:r.status==='历史窗口已结束'}">{{r.status}}</span></div><h3>{{r.title}}</h3><p>{{r.summary}}</p><dl><dt>整理方式 / 复核</dt><dd>{{r.curation==='manual'?'人工整理':'AI 整理'}} / {{r.reviewStatus}}</dd><dt>资料期间</dt><dd>{{r.period}}</dd><dt>口径与适用边界</dt><dd>{{r.scope}}</dd><dt>业务提示</dt><dd>{{r.impact}}</dd><dt>来源 / 发布日期</dt><dd>{{r.publisher}} / {{r.published}}</dd><dt>原文定位</dt><dd>{{r.location}}</dd></dl><small v-if="r.license">{{r.license}}</small><div class="source-bottom"><small>{{r.id}} · {{r.delivery}}</small><a :href="r.url" target="_blank" rel="noopener noreferrer">查看官方原文 ↗</a></div></article></section></template>
<style>.curation-tabs{display:flex;gap:8px;border-bottom:1px solid #e5e8eb;margin:15px 0;padding-bottom:12px}.curation-tabs button{border:0;border-radius:20px;background:#f5f6f7;color:#66717a;padding:10px 18px;font-size:13px}.curation-tabs button.selected{background:#202124;color:#fff}.curation-badge{border-radius:5px;padding:3px 8px}.curation-badge.ai{background:#eeeafa;color:#7456a4}.curation-badge.manual{background:#e6f4ed;color:#287452}.source-meta{gap:12px;flex-wrap:wrap}.official-sources{margin:28px 0}.source-disclosure{color:#667780;font-size:12px;line-height:1.8;background:#f0f7f9;padding:14px;border-radius:10px}.source-filters{display:flex;gap:12px;margin:18px 0}.source-filters .el-input{flex:1}.source-filters .el-select{width:155px}.official-card{padding:23px;border:1px solid #dde4e7;border-radius:14px;margin:15px 0;background:#fff}.source-meta{display:flex;justify-content:space-between;color:#2383a3;font-size:11px}.source-meta .historical{color:#a36e12}.official-card h3{font-size:17px;margin-top:15px}.official-card>p{font-size:13px;color:#52616b}.official-card dl{grid-template-columns:130px 1fr;line-height:1.8;gap:10px}.source-bottom{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-top:18px;border-top:1px solid #eee;padding-top:15px}.source-bottom a{color:#1483aa;font-size:12px;text-decoration:underline}@media(max-width:650px){.source-filters,.source-bottom{flex-direction:column;align-items:stretch}.source-filters .el-select{width:100%}.official-card{padding:16px}.official-card dl{grid-template-columns:1fr;gap:5px}.official-card dd{margin-bottom:9px}}
</style>
